-- satie stdlib: encoding (DIMACS/WCNF text builders for embedding code).
local Encoding = {}

Encoding.lit_str = function(lit)
  if lit < 0 then return "-" .. (-lit) end
  return str(lit)
end

Encoding.clause_str = function(lits)
  local out = ""
  local i = 1
  while i <= #lits do
    if i ~= 1 then out = out .. " " end
    out = out .. Encoding.lit_str(lits[i])
    i = i + 1
  end
  return out .. " 0"
end

Encoding.cnf_str = function(clauses, header)
  local out = ""
  if header then
    local vars = 0
    local i = 1
    while i <= #clauses do
      local j = 1
      while j <= #clauses[i] do
        local v = clauses[i][j]
        if v < 0 then v = -v end
        if v > vars then vars = v end
        j = j + 1
      end
      i = i + 1
    end
    out = "p cnf " .. str(vars) .. " " .. str(#clauses) .. "\n"
  end
  local i = 1
  while i <= #clauses do
    out = out .. Encoding.clause_str(clauses[i]) .. "\n"
    i = i + 1
  end
  return out
end

Encoding.wcnf_str = function(hard, soft, top)
  local out = "c wcnf generated by satie stdlib\n"
  local total = #hard + #soft
  out = out .. "p wcnf 0 " .. str(total) .. " " .. str(top) .. "\n"
  local i = 1
  while i <= #hard do
    out = out .. str(top) .. " " .. Encoding.clause_str(hard[i]) .. "\n"
    i = i + 1
  end
  i = 1
  while i <= #soft do
    out = out .. str(soft[i][1]) .. " " .. Encoding.clause_str(soft[i][2]) .. "\n"
    i = i + 1
  end
  return out
end

return Encoding
